-- Cập nhật bổ sung catalog tour niêm yết công khai ở Huế (không xóa hoặc sửa tour hiện có).
-- Chạy trên HueTourDb đã được tạo bằng HueTour_SchemaAndData.sql.
IF COL_LENGTH(N'dbo.TourDuLich', N'DonViToChuc') IS NULL
    ALTER TABLE dbo.TourDuLich ADD DonViToChuc NVARCHAR(200) NULL;
IF COL_LENGTH(N'dbo.TourDuLich', N'NguonGia') IS NULL
    ALTER TABLE dbo.TourDuLich ADD NguonGia NVARCHAR(1000) NULL;
IF COL_LENGTH(N'dbo.TourDuLich', N'NgayKiemTraGia') IS NULL
    ALTER TABLE dbo.TourDuLich ADD NgayKiemTraGia DATE NULL;
GO

CREATE OR ALTER VIEW dbo.Tour AS
SELECT MaTour AS Id, MaTourHienThi AS Code, TenTour AS Title, DanhMuc AS Category,
       MoTaNgan AS ShortDescription, MoTaChiTiet AS Description, LichTrinh AS Itinerary,
       DiemNoiBat AS Highlights, ThoiLuong AS Duration, DiemKhoiHanh AS StartingLocation,
       GiaCoBan AS BasePrice, DuongDanAnh AS ImageUrl, DonViToChuc AS ProviderName,
       NguonGia AS SourceUrl, NgayKiemTraGia AS PriceVerifiedAt,
       DangMoBan AS IsActive, NgayTao AS CreatedAt
FROM dbo.TourDuLich;
GO

DECLARE @SourceUrl NVARCHAR(1000) = N'https://huetripo.hue.gov.vn/tour-du-lich/danh-sach-tour';
DECLARE @PriceVerifiedAt DATE = '20261022';

INSERT INTO dbo.Tour (Code, Title, Category, ShortDescription, Description, Itinerary, Highlights, Duration, StartingLocation, BasePrice, ImageUrl, ProviderName, SourceUrl, PriceVerifiedAt, IsActive)
SELECT source.Code, source.Title, source.Category, source.ShortDescription, source.Description,
       source.Itinerary, source.Highlights, source.Duration, source.StartingLocation,
       source.BasePrice, source.ImageUrl, source.ProviderName, source.SourceUrl,
       source.PriceVerifiedAt, 1
FROM (VALUES
    ('HT-MARKET-THANHTAN24', N'[Huế] Huế – Suối khoáng nóng Thanh Tân – Huế', N'Thiên nhiên & Nghỉ dưỡng', N'Tour ghép một ngày từ Huế đến khu suối khoáng nóng Thanh Tân.', N'Tour được niêm yết trên HueTripO ngày 22/10/2026 với giá từ 950.000đ/khách. Lịch trình chi tiết, giá cuối cùng và dịch vụ cần xác nhận với Công ty CP Du lịch Đại Bàng.', N'Huế -> Khu suối khoáng nóng Thanh Tân -> Huế. Hoạt động theo xác nhận của đơn vị tổ chức.', N'Suối khoáng nóng Thanh Tân; tour ghép; giá tham khảo từ 950.000đ/khách.', N'1 Ngày', N'Huế', CAST(950000 AS DECIMAL(18,2)), N'/images/thien-mu-2025.jpg', N'Công ty CP Du lịch Đại Bàng', @SourceUrl, @PriceVerifiedAt),
    ('HT-MARKET-BACHMA25', N'Huế – Vườn Quốc gia Bạch Mã – Hải Vọng Đài – Ngũ Hồ – Thác Đỗ Quyên', N'Sinh thái & Đầm phá', N'Tour ghép một ngày từ Huế đến các điểm nổi bật tại Vườn Quốc gia Bạch Mã.', N'Tour được niêm yết trên HueTripO ngày 22/10/2026 với giá từ 1.050.000đ/khách. Giá, lịch, điều kiện thời tiết và dịch vụ cần xác nhận với Công ty CP Du lịch Đại Bàng.', N'Huế -> Vườn Quốc gia Bạch Mã -> Hải Vọng Đài -> Ngũ Hồ -> Thác Đỗ Quyên -> Huế.', N'Vườn Quốc gia Bạch Mã; Hải Vọng Đài; Ngũ Hồ; thác Đỗ Quyên; giá từ 1.050.000đ/khách.', N'1 Ngày', N'Huế', CAST(1050000 AS DECIMAL(18,2)), N'/images/bach-ma-waterfall.jpg', N'Công ty CP Du lịch Đại Bàng', @SourceUrl, @PriceVerifiedAt),
    ('HT-MARKET-TAMGIANG3D26', N'Hoàng hôn trên phá Tam Giang – Vườn Quốc gia Bạch Mã', N'Sinh thái & Đầm phá', N'Hành trình ghép đoàn ba ngày kết hợp phá Tam Giang và Vườn Quốc gia Bạch Mã.', N'Tour được niêm yết trên HueTripO ngày 22/10/2026 với giá từ 3.990.000đ/khách; điểm đón gồm sân bay Phú Bài, ga Huế hoặc bến xe. Lịch trình cần xác nhận với An Tường Travel.', N'Sân bay Phú Bài / Ga Huế / Bến xe -> Phá Tam Giang -> Vườn Quốc gia Bạch Mã -> Kết thúc theo chương trình An Tường Travel.', N'Phá Tam Giang; Vườn Quốc gia Bạch Mã; tour ghép ba ngày; giá từ 3.990.000đ/khách.', N'3 Ngày', N'Sân bay Phú Bài / Ga Huế / Bến xe', CAST(3990000 AS DECIMAL(18,2)), N'/images/tam-giang-2024.jpg', N'Công ty TNHH Lữ hành An Tường Travel', @SourceUrl, @PriceVerifiedAt),
    ('HT-MARKET-TAMGIANG2D27', N'Cố đô Huế – Hoàng hôn trên phá Tam Giang – Hoàng cung – Lăng Khải Định – Chùa Thiên Mụ – Chợ Đông Ba', N'Di tích Cố Đô', N'Tour ghép hai ngày một đêm kết hợp di sản Huế và hoàng hôn trên phá Tam Giang.', N'Tour được niêm yết trên HueTripO ngày 22/10/2026 với giá từ 2.890.000đ/khách. Lịch trình từng ngày và dịch vụ cần xác nhận với An Tường Travel.', N'Sân bay Phú Bài / Ga Huế / Bến xe -> Hoàng cung -> Lăng Khải Định -> Chùa Thiên Mụ -> Chợ Đông Ba -> Phá Tam Giang. Lịch chi tiết theo nhà cung cấp.', N'Hoàng cung; lăng Khải Định; chùa Thiên Mụ; chợ Đông Ba; phá Tam Giang; giá từ 2.890.000đ/khách.', N'2 Ngày 1 Đêm', N'Sân bay Phú Bài / Ga Huế / Bến xe', CAST(2890000 AS DECIMAL(18,2)), N'/images/imperial-city-2025.jpg', N'Công ty TNHH Lữ hành An Tường Travel', @SourceUrl, @PriceVerifiedAt),
    ('HT-MARKET-TAMGIANG-SUNSET28', N'Trải nghiệm trên phá Tam Giang – Ngắm hoàng hôn', N'Sinh thái & Đầm phá', N'Tour ghép nửa ngày khởi hành từ thành phố Huế.', N'Tour được niêm yết trên HueTripO ngày 22/10/2026 với giá từ 850.000đ/khách. Lịch, hoạt động trên phá và chỗ trống cần xác nhận với Restour.', N'Thành phố Huế -> Phá Tam Giang -> Ngắm hoàng hôn -> Trở về Huế. Chi tiết theo chương trình Restour.', N'Phá Tam Giang; ngắm hoàng hôn; tour ghép nửa ngày; giá từ 850.000đ/khách.', N'Nửa Ngày', N'Thành phố Huế', CAST(850000 AS DECIMAL(18,2)), N'/images/tam-giang-2024.jpg', N'Công ty TNHH MTV Restour', @SourceUrl, @PriceVerifiedAt),
    ('HT-MARKET-SONGHUONG-TEA29', N'Trà chiều trên sông Hương – Du thuyền ngắm hoàng hôn', N'Sông Hương & Làng nghề', N'Trải nghiệm ghép nửa ngày trên sông Hương, thưởng trà và ngắm hoàng hôn.', N'Tour được niêm yết trên HueTripO ngày 22/10/2026 với giá từ 450.000đ/khách. Giờ chạy, nội dung phục vụ và chỗ trống cần xác nhận với Restour.', N'Thành phố Huế -> Du thuyền sông Hương -> Trà chiều và ngắm hoàng hôn -> Kết thúc theo chương trình Restour.', N'Du thuyền sông Hương; trà chiều; ngắm hoàng hôn; giá từ 450.000đ/khách.', N'Nửa Ngày', N'Thành phố Huế', CAST(450000 AS DECIMAL(18,2)), N'/images/thien-mu-2025.jpg', N'Công ty TNHH MTV Restour', @SourceUrl, @PriceVerifiedAt),
    ('HT-MARKET-THUYBIEU30', N'Khám phá Thủy Biều', N'Sông Hương & Làng nghề', N'Tour ghép nửa ngày khám phá khu vực Thủy Biều, khởi hành từ thành phố Huế.', N'Tour được niêm yết trên HueTripO ngày 22/10/2026 với giá từ 850.000đ/khách. Nội dung và chỗ trống cần xác nhận với Restour.', N'Thành phố Huế -> Khám phá Thủy Biều -> Trở về Huế. Các điểm dừng theo chương trình Restour.', N'Thủy Biều; tour ghép nửa ngày; giá từ 850.000đ/khách.', N'Nửa Ngày', N'Thành phố Huế', CAST(850000 AS DECIMAL(18,2)), N'/images/thien-mu-2025.jpg', N'Công ty TNHH MTV Restour', @SourceUrl, @PriceVerifiedAt),
    ('HT-MARKET-FOODTOUR31', N'Khám phá ẩm thực xứ Huế – Hue Food Tour', N'Văn hóa & Ẩm thực', N'Tour tự chọn nửa ngày khám phá ẩm thực Huế, khởi hành từ thành phố Huế.', N'Tour được niêm yết trên HueTripO ngày 22/10/2026 với giá từ 850.000đ/khách. Món ăn, điểm dừng và dịch vụ bao gồm cần xác nhận với Restour.', N'Thành phố Huế -> Trải nghiệm ẩm thực theo chương trình Hue Food Tour -> Kết thúc tại Huế.', N'Ẩm thực Huế; tour tự chọn; nửa ngày; giá từ 850.000đ/khách.', N'Nửa Ngày', N'Thành phố Huế', CAST(850000 AS DECIMAL(18,2)), N'/images/bun-bo-hue-2024.jpg', N'Công ty TNHH MTV Restour', @SourceUrl, @PriceVerifiedAt),
    ('HT-MARKET-VIETRAVEL32', N'Huế – Đại Nội – Lăng Khải Định', N'Di tích Cố Đô', N'Tour ghép một ngày khởi hành tại 01 Hùng Vương, thành phố Huế.', N'Tour được niêm yết trên HueTripO ngày 22/10/2026 với giá từ 890.000đ/khách. Lịch, giá cuối cùng, dịch vụ và chỗ trống cần xác nhận với Vietravel Huế.', N'01 Hùng Vương, TP Huế -> Đại Nội Huế -> Lăng Khải Định -> Kết thúc theo lịch Vietravel Huế.', N'Đại Nội Huế; lăng Khải Định; tour ghép một ngày; giá từ 890.000đ/khách.', N'1 Ngày', N'01 Hùng Vương, TP Huế', CAST(890000 AS DECIMAL(18,2)), N'/images/imperial-city-2025.jpg', N'Công ty TNHH MTV Du lịch Vietravel Huế', @SourceUrl, @PriceVerifiedAt),
    ('HT-MARKET-BAOVINH33', N'Huế – Phố cổ Bao Vinh – Tranh làng Sình – Làng hoa giấy Thanh Tiên – Bữa trưa dân dã', N'Văn hóa & Ẩm thực', N'Tour ghép nửa ngày kết nối phố cổ Bao Vinh với làng nghề và bữa trưa địa phương.', N'Tour được niêm yết trên HueTripO ngày 22/10/2026 với giá từ 750.000đ/khách. Lịch trình, bữa trưa và chỗ trống cần xác nhận với Công ty CP Du lịch Đại Bàng.', N'Thành phố Huế -> Phố cổ Bao Vinh -> Tranh làng Sình -> Làng hoa giấy Thanh Tiên -> Bữa trưa dân dã. Thứ tự theo nhà cung cấp.', N'Phố cổ Bao Vinh; tranh làng Sình; làng hoa giấy Thanh Tiên; bữa trưa dân dã; giá từ 750.000đ/khách.', N'Nửa Ngày', N'Thành phố Huế', CAST(750000 AS DECIMAL(18,2)), N'/images/dong-ba-market-2024.jpg', N'Công ty CP Du lịch Đại Bàng', @SourceUrl, @PriceVerifiedAt),
    ('HT-MARKET-HITOUR1D34', N'Tour du lịch Huế trong ngày – Thiên Mụ, Đại Nội, hai lăng và làng nghề', N'Di tích Cố Đô', N'Tour khởi hành hằng ngày từ Huế, tham quan di sản và làng nghề truyền thống.', N'Hitour công bố giá người lớn 850.000đ, áp dụng từ 01/01 đến 31/12/2026; lịch khởi hành hằng ngày. Xác nhận lại giá và chỗ với đơn vị trước khi đặt.', N'Chùa Thiên Mụ; Đại Nội; chợ Đông Ba; lăng Minh Mạng; lăng Khải Định; làng nón; làng hương; giá niêm yết 2026.', N'08:00 Đón tại khách sạn trung tâm Huế -> Chùa Thiên Mụ -> Đại Nội -> Chợ Đông Ba -> Lăng Minh Mạng -> Lăng Khải Định -> Làng nón, làng hương -> 16:30 Trả khách.', N'1 Ngày', N'Trung tâm thành phố Huế', CAST(850000 AS DECIMAL(18,2)), N'/images/imperial-city-2025.jpg', N'Hitour', N'https://hitour.vn/tour-du-lich-hue/tour-du-lich-hue-1-ngay-tu-thua-thien-hue', @PriceVerifiedAt)
) AS source(Code, Title, Category, ShortDescription, Description, Itinerary, Highlights, Duration, StartingLocation, BasePrice, ImageUrl, ProviderName, SourceUrl, PriceVerifiedAt)
WHERE NOT EXISTS (SELECT 1 FROM dbo.Tour existing WHERE existing.Code = source.Code);
